# 2-layer vs 4-layer networks on red/blue balls. Same data, same optimiser, same number of
# weight updates. Each network gets the learning rate that works best for it on a validation
# set; the test sets are used once, at the end, over 10 fresh seeds.
import math
import matplotlib.pyplot as plt, numpy as np, pandas as pd, torch, torch.nn as nn
from scipy import stats
from sklearn.datasets import make_moons

torch.set_num_threads(4)
EPOCHS, BATCH, N_TRAIN = 100, 64, 2000
LRS, TUNE_SEEDS, SEEDS = (3e-4, 1e-3, 3e-3, 1e-2), (100, 101), range(10)
WIDTH = 16


def spirals(n, noise=0.2, seed=0, part=(0.0, 1.0)):
    """Two interleaved spirals, two turns each. `part` keeps a stretch of each arm (0 = centre, 1 = tip)."""
    r = np.random.default_rng(seed)
    t = np.sqrt(r.uniform(part[0] ** 2, part[1] ** 2, n // 2)) * 4 * np.pi
    arm = np.c_[t * np.cos(t), t * np.sin(t)]
    X = np.r_[arm, -arm] + r.normal(0, noise, (n, 2))
    return X, np.r_[np.zeros(n // 2), np.ones(n // 2)].astype(int)


def moons(n, noise=0.2, seed=0):
    return make_moons(n, noise=noise, random_state=seed)


# Each task: training data, validation, and the tests of generalisation (data the nets never saw).
TASKS = {
    "moons": dict(make=moons, noise=0.2, tests={"test (same distribution)": dict(), "noisier balls": dict(noise=0.3)}),
    "spirals": dict(make=spirals, noise=0.2, tests={"test (same distribution)": dict(), "noisier balls": dict(noise=0.3)}),
}

count = lambda sizes: sum(a * b + b for a, b in zip(sizes, sizes[1:]))
deep = [WIDTH] * 3
same_weights = round((count([2, *deep, 2]) - 2) / 5)  # one hidden layer: 2h + h + 2h + 2 weights
ARCHS = {"2-layer, same width": [WIDTH], "4-layer": deep, "2-layer, same weights": [same_weights]}


def tensors(X, y, scale):
    return torch.tensor((X - scale[0]) / scale[1], dtype=torch.float32), torch.tensor(y)


def mlp(hidden):
    layers, prev = [], 2
    for h in hidden:
        layers += [nn.Linear(prev, h), nn.ReLU()]
        prev = h
    return nn.Sequential(*layers, nn.Linear(prev, 2))


@torch.no_grad()
def accuracy(net, X, y):
    return (net(X).argmax(1) == y).float().mean().item()


def train(hidden, lr, seed, X, y):
    """The same number of weight updates whatever the training set's size (EPOCHS over N_TRAIN points)."""
    torch.manual_seed(seed)
    net = mlp(hidden)
    opt, loss = torch.optim.Adam(net.parameters(), lr=lr), nn.CrossEntropyLoss()
    steps, done = EPOCHS * math.ceil(N_TRAIN / BATCH), 0
    while done < steps:
        for idx in torch.randperm(len(X)).split(BATCH):
            opt.zero_grad()
            loss(net(X[idx]), y[idx]).backward()
            opt.step()
            done += 1
            if done == steps:
                break
    return net


def ci95(a):
    return stats.t.ppf(0.975, len(a) - 1) * np.std(a, ddof=1) / math.sqrt(len(a))


rows, verdicts, nets = [], [], {}
for task, spec in TASKS.items():
    X, y = spec["make"](N_TRAIN + 500, noise=spec["noise"], seed=0)
    scale = (X[:N_TRAIN].mean(0), X[:N_TRAIN].std(0))
    Xtr, ytr = tensors(X[:N_TRAIN], y[:N_TRAIN], scale)
    Xval, yval = tensors(X[N_TRAIN:], y[N_TRAIN:], scale)
    tests = {name: tensors(*spec["make"](1000, **{"noise": spec["noise"], **kw}, seed=1), scale) for name, kw in spec["tests"].items()}
    small = tensors(*spec["make"](200, noise=spec["noise"], seed=2), scale)
    if task == "spirals":  # trained on the inner 70% of each arm, tested on the outer 30%
        inner = tensors(*spirals(N_TRAIN, seed=3, part=(0.0, 0.7)), scale)
        outer = tensors(*spirals(1000, seed=4, part=(0.7, 1.0)), scale)
    scores = {}
    for name, hidden in ARCHS.items():
        lr = max(LRS, key=lambda lr: np.mean([accuracy(train(hidden, lr, s, Xtr, ytr), Xval, yval) for s in TUNE_SEEDS]))
        runs = {k: [] for k in ["train", *tests, "trained on 200 points"] + (["outer arm (extrapolation)"] if task == "spirals" else [])}
        for s in SEEDS:
            net = train(hidden, lr, s, Xtr, ytr)
            runs["train"].append(accuracy(net, Xtr, ytr))
            for t, (Xt, yt) in tests.items():
                runs[t].append(accuracy(net, Xt, yt))
            runs["trained on 200 points"].append(accuracy(train(hidden, lr, s, *small), *tests["test (same distribution)"]))
            if task == "spirals":
                runs["outer arm (extrapolation)"].append(accuracy(train(hidden, lr, s, *inner), *outer))
            if s == 0:
                nets[task, name] = (net, scale)
        scores[name] = runs
        rows.append({"task": task, "network": name, "weights": count([2, *hidden, 2]), "lr": lr,
                     **{k: f"{np.mean(v):.3f} ± {ci95(v):.3f}" for k, v in runs.items()}})
        print(f"{task}: {name} done (lr {lr:g})", flush=True)
    for other in ("2-layer, same width", "2-layer, same weights"):
        for t in scores["4-layer"]:
            if t == "train":
                continue
            a, b = np.array(scores["4-layer"][t]), np.array(scores[other][t])
            p = stats.ttest_ind(a, b, equal_var=False).pvalue if (a.std() + b.std()) > 0 else 1.0
            verdicts.append({"task": task, "4-layer vs": other, "test": t, "difference": round(a.mean() - b.mean(), 4), "p (Welch)": float(f"{p:.2g}"),
                             "verdict": "4-layer better" if p < 0.01 and a.mean() > b.mean() else "2-layer better" if p < 0.01 else "no clear difference"})

print("\nAccuracy, mean ± 95% CI over 10 seeds (each network at its own best learning rate):")
display(pd.DataFrame(rows).set_index(["task", "network"]))
display(pd.DataFrame(verdicts).set_index(["task", "4-layer vs", "test"]))

xx, yy = np.meshgrid(np.linspace(-2.2, 2.2, 200), np.linspace(-2.2, 2.2, 200))
grid = torch.tensor(np.c_[xx.ravel(), yy.ravel()], dtype=torch.float32)
fig, axes = plt.subplots(2, 3, figsize=(10.5, 7), layout="constrained")
for row, task in zip(axes, TASKS):
    X, y = TASKS[task]["make"](600, noise=TASKS[task]["noise"], seed=1)
    for ax, name in zip(row, ARCHS):
        net, (mu, sd) = nets[task, name]
        with torch.no_grad():
            p = net(grid).softmax(1)[:, 1].reshape(xx.shape)
        ax.contourf(xx, yy, p, levels=12, cmap="RdBu_r", alpha=0.55)
        Xs = (X - mu) / sd
        ax.scatter(*Xs.T, c=y, cmap="RdBu_r", edgecolors="k", linewidths=0.3, s=9)
        ax.set_title(f"{task}: {name}", fontsize=10)
        ax.set_xticks([]), ax.set_yticks([])
fig.suptitle("Decision boundaries (seed 0) on new test balls")
plt.show()
